import assert from 'node:assert/strict';
import fs from 'node:fs';
import { syncBuiltinESMExports } from 'node:module';
import { readFile, readlink, readdir, mkdtemp, writeFile, chmod, rm, mkdir } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { once } from 'node:events';
import http from 'node:http';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root=fileURLToPath(new URL('../../',import.meta.url));
const binary=path.join(root,'x10/.build/objs/nginx');
const source=path.join(root,'x10/control/listeners.mjs');
const hash=v=>createHash('sha256').update(v).digest('hex');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const report={schemaVersion:1,suite:'independent-listener-observer-review',startedAt:new Date().toISOString(),tests:[],limitations:['Reviewer short actual native fixture; not a full native protocol matrix, complete process-set proof or cutover fence.']};
let prefix,child,port,config;
let output='';
async function test(name,fn){const details=await fn();report.tests.push({name,passed:true,...(details||{})});}
async function wait(fn,ms=4000){const stop=Date.now()+ms;let last;while(Date.now()<stop){try{const x=await fn();if(x)return x;}catch(e){last=e;}await sleep(20);}throw last||new Error('deadline');}
async function get(){return new Promise((resolve,reject)=>{const q=http.get({host:'127.0.0.1',port,path:'/',agent:false,headers:{connection:'close'}},s=>{let body='';s.on('data',b=>body+=b);s.on('error',reject);s.on('end',()=>resolve(body));});const t=setTimeout(()=>q.destroy(new Error('request deadline')),500);q.once('close',()=>clearTimeout(t));q.once('error',reject);});}
async function identity(){const pid=child.pid;let procPid;for(const e of await readdir('/proc')){if(!/^\d+$/.test(e))continue;try{const s=await readFile(`/proc/${e}/status`,'utf8');if(Number(/^NSpid:\s+([\d\s]+)$/m.exec(s)?.[1].trim().split(/\s+/).at(-1))===pid&&await readlink(`/proc/${e}/exe`)===binary){procPid=Number(e);break;}}catch{}}
 assert.ok(procPid);const stat=await readFile(`/proc/${procPid}/stat`,'utf8');const fields=stat.slice(stat.lastIndexOf(') ')+2).split(' ');const command=(await readFile(`/proc/${procPid}/cmdline`,'utf8')).split('\0')[0];return {pid,procPid,pidNamespace:await readlink(`/proc/${procPid}/ns/pid`),startTicks:fields[19],uid:process.getuid(),executable:binary,commandSha256:hash(command)};}
async function stop(){if(child&&child.exitCode===null&&child.signalCode===null){child.kill('SIGQUIT');try{await wait(()=>child.exitCode!==null||child.signalCode!==null,3000);}catch{child.kill('SIGTERM');await wait(()=>child.exitCode!==null||child.signalCode!==null,1000).catch(()=>{});}}if(child){try{process.kill(-child.pid,'SIGKILL');}catch(e){if(e.code!=='ESRCH')throw e;}}}
try{
 report.sourceSha256=hash(await readFile(source));report.binarySha256=hash(await readFile(binary));
 const {captureTcpListeners,inspectTcpListeners}=await import(source);
 prefix=await mkdtemp(path.join(os.tmpdir(),'x10-listener-review-'));await chmod(prefix,0o700);await mkdir(path.join(prefix,'logs'));
 const n=net.createServer();n.listen(0,'127.0.0.1');await once(n,'listening');port=n.address().port;await new Promise(r=>n.close(r));
 config=path.join(prefix,'nginx.conf');const render=text=>`${process.getuid()===0?`user ${os.userInfo().username};`:''}\ndaemon off; master_process on; worker_processes 1; pid ${prefix}/nginx.pid; error_log ${prefix}/error.log notice; events { worker_connections 128; } http { access_log off; server { listen 127.0.0.1:${port}; location / { return 200 \"${text}\"; } } }\n`;
 await writeFile(config,render('A'),{mode:0o600});child=spawn(binary,['-p',`${prefix}/`,'-c',config],{detached:true,stdio:['ignore','pipe','pipe']});for(const p of [child.stdout,child.stderr])p.on('data',b=>output=(output+b).slice(-8192));await wait(async()=>await get()==='A');
 const master=await identity(),options={master,port,binary};let snapshot;
 await test('actual-native-capture-and-pid-namespace-mapping',async()=>{snapshot=await captureTcpListeners(options);assert.equal(snapshot.scope,'captured-processes-only');assert.ok(snapshot.processes.length>0);return {masterLocalPid:master.pid,masterProcPid:master.procPid,namespaceIdsDiffer:master.pid!==master.procPid,capturedProcesses:snapshot.processes.length};});
 await test('actual-live-listener-owner-is-pending',async()=>{const x=await inspectTcpListeners(snapshot,options);assert.equal(x.state,'pending');assert.equal(x.closed,false);return {state:x.state};});
 const resign=s=>{delete s.sha256;s.sha256=hash(JSON.stringify(s));return s;};
 await test('accidentally-edited-snapshot-rejected',async()=>{const s=structuredClone(snapshot);s.capturedAt='changed';await assert.rejects(inspectTcpListeners(s,options));});
 await test('hash-valid-empty-process-snapshot-rejected',async()=>{const s=structuredClone(snapshot);s.processes=[];resign(s);await assert.rejects(inspectTcpListeners(s,options));});
 await test('context-port-mismatch-rejected',async()=>{await assert.rejects(inspectTcpListeners(snapshot,{...options,port:port===65535?port-1:port+1}));});
 await test('context-master-starttime-mismatch-rejected',async()=>{await assert.rejects(inspectTcpListeners(snapshot,{...options,master:{...master,startTicks:String(BigInt(master.startTicks)+1n)}}));});
 await test('context-binary-mismatch-rejected',async()=>{await assert.rejects(inspectTcpListeners(snapshot,{...options,binary:'/bin/false'}));});
 const procPid=snapshot.processes.find(p=>p.ownedListenerFds.length).procPid;
 async function patch(name,replacement,fn){const original=fs.promises[name];fs.promises[name]=replacement(original);syncBuiltinESMExports();try{return await fn();}finally{fs.promises[name]=original;syncBuiltinESMExports();}}
 await test('actual-child-fd-directory-EACCES-is-unresolved',async()=>patch('opendir',original=>async(...a)=>{if(a[0]===`/proc/${procPid}/fd`)throw Object.assign(new Error('review permission control'),{code:'EACCES'});return original(...a);},async()=>{await assert.rejects(inspectTcpListeners(snapshot,options),e=>e.code==='listener_observation_unavailable'&&e.message.includes('EACCES'));}));
 await test('actual-child-transient-fd-ENOENT-retries-inventory',async()=>{let calls=0;return patch('readlink',original=>async(...a)=>{if(String(a[0]).startsWith(`/proc/${procPid}/fd/`)&&calls++===0)throw Object.assign(new Error('review one descriptor race'),{code:'ENOENT'});return original(...a);},async()=>{const r=await inspectTcpListeners(snapshot,options);assert.equal(r.state,'pending');assert.ok(calls>1);return {descriptorReads:calls};});});
 await test('actual-child-persistent-fd-ENOENT-remains-unresolved',async()=>{let calls=0;return patch('readlink',original=>async(...a)=>{if(String(a[0]).startsWith(`/proc/${procPid}/fd/`)){calls++;throw Object.assign(new Error('review exhausted descriptor race'),{code:'ENOENT'});}return original(...a);},async()=>{await assert.rejects(inspectTcpListeners(snapshot,options),e=>e.code==='listener_observation_unavailable'&&e.message.includes('ENOENT'));assert.equal(calls,3);return {descriptorAttempts:calls};});});
 await test('hash-valid-child-starttime-change-is-unresolved',async()=>{const s=structuredClone(snapshot);s.processes[0].startTicks=String(BigInt(s.processes[0].startTicks)+1n);resign(s);await assert.rejects(inspectTcpListeners(s,options),e=>e.code==='listener_observation_unavailable'&&e.message.includes('identity changed'));});
 await test('actual-delayed-status-open-closes-acquired-handle',async()=>{let handle,closed=false;await patch('open',original=>async(...a)=>{if(a[0]!==`/proc/${master.procPid}/status`)return original(...a);handle=await original(...a);const close=handle.close.bind(handle);handle.close=async()=>{closed=true;return close();};await sleep(3100);return handle;},async()=>{await assert.rejects(captureTcpListeners(options),e=>e.code==='listener_observation_unavailable'&&e.message.includes('budget'));});const observerClosed=closed;if(handle&&!closed)await handle.close();assert.equal(observerClosed,true);return {acquiredHandleClosedByObserver:observerClosed};});
 await test('actual-delayed-fd-opendir-closes-acquired-directory',async()=>{let dir,closed=false;await patch('opendir',original=>async(...a)=>{if(a[0]!==`/proc/${procPid}/fd`)return original(...a);dir=await original(...a);const close=dir.close.bind(dir);dir.close=async()=>{closed=true;return close();};await sleep(3100);return dir;},async()=>{await assert.rejects(captureTcpListeners(options),e=>e.code==='listener_observation_unavailable'&&e.message.includes('budget'));});const observerClosed=closed;if(dir&&!closed)await dir.close();assert.equal(observerClosed,true);return {acquiredDirectoryClosedByObserver:observerClosed};});
 await writeFile(config,render('B'));child.kill('SIGHUP');await wait(async()=>await get()==='B');
 await test('actual-captured-worker-release-after-reload',async()=>{const x=await wait(async()=>{const r=await inspectTcpListeners(snapshot,options);return r.closed?r:null;});assert.equal(x.state,'closed');return {state:x.state,observedProcesses:x.processes};});
 await stop();
 await test('stopped-master-does-not-count-as-closure',async()=>{await assert.rejects(inspectTcpListeners(snapshot,options));});
 report.success=true;
}catch(e){report.success=false;report.failure={message:e.message,stack:e.stack};}
finally{await stop().catch(e=>report.cleanupError=e.message);if(prefix)await rm(prefix,{recursive:true,force:true});report.cleanup={nativeStopped:!child||child.exitCode!==null||child.signalCode!==null,nativeExitCode:child?.exitCode??null,nativeSignal:child?.signalCode??null,temporaryRootRemoved:true};report.sourceUnchangedDuringTest=report.sourceSha256===hash(await readFile(source));report.binaryUnchangedDuringTest=report.binarySha256===hash(await readFile(binary));report.childOutput=output;report.finishedAt=new Date().toISOString();console.log(JSON.stringify(report,null,2));if(!report.success||!report.sourceUnchangedDuringTest||!report.binaryUnchangedDuringTest||report.cleanupError)process.exitCode=1;}

import {spawn} from 'node:child_process';
import {readFile,readdir,readlink,lstat} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import path from 'node:path';
const fixture=path.resolve('x10/test/handover-baseline.mjs');
const digest=b=>createHash('sha256').update(b).digest('hex');
const fixtureSha256=digest(await readFile(fixture));
let stdout='',stderr='',child,master,worker,procPid,interrupted=false;
const delay=ms=>new Promise(r=>setTimeout(r,ms));
const report={suite:'independent-handover-interruption',fixtureSha256,startedAt:new Date().toISOString()};
async function wait(fn,ms){const stop=Date.now()+ms;while(Date.now()<stop){const r=await fn();if(r)return r;await delay(10);}throw new Error('review interruption deadline');}
try{
 child=spawn(process.execPath,[fixture],{stdio:['ignore','pipe','pipe']});
 child.stdout.on('data',b=>{stdout+=b;if(stdout.length>1024*1024)child.kill('SIGTERM');});child.stderr.on('data',b=>stderr=(stderr+b).slice(-8192));
 const match=await wait(()=>/old worker stopped; master=(\d+) worker=(\d+)/.exec(stderr),6000);master=Number(match[1]);worker=Number(match[2]);
 const ownNs=await readlink('/proc/self/ns/pid');
 for(const p of await readdir('/proc')){if(!/^\d+$/.test(p))continue;try{const status=await readFile(`/proc/${p}/status`,'utf8');const local=Number(/^NSpid:\s+([\d\s]+)$/m.exec(status)?.[1].trim().split(/\s+/).at(-1));if(local===worker&&await readlink(`/proc/${p}/ns/pid`)===ownNs){procPid=Number(p);report.observedStoppedWorker=/^State:\s+T\b/m.test(status);break;}}catch{}}
 if(!report.observedStoppedWorker)throw new Error('worker stop independently unconfirmed');
 const start=performance.now();child.kill('SIGTERM');interrupted=true;await wait(()=>child.exitCode!==null||child.signalCode!==null,5000);report.elapsedAfterSignalMs=performance.now()-start;
 const result=JSON.parse(stdout);report.harnessExitCode=child.exitCode;report.harnessSignal=child.signalCode;report.result={success:result.success,interrupted:result.interrupted,stopSignal:result.stopSignal,cleanup:result.cleanup};
 let gone=false;try{await lstat(`/proc/${procPid}`);}catch(e){if(e.code==='ENOENT')gone=true;else throw e;}report.stoppedWorkerGone=gone;
 report.success=child.exitCode===1&&child.signalCode===null&&result.success===false&&result.interrupted===true&&result.stopSignal==='SIGTERM'&&result.cleanup?.stoppedWorkerResumeRequested===true&&result.cleanup.nativeStopped===true&&result.cleanup.fixturesStopped===true&&result.cleanup.openSockets===0&&result.cleanup.temporaryRootRemoved===true&&result.cleanup.errors.length===0&&gone;
}catch(e){report.success=false;report.error=e.stack||e.message;}
finally{
 if(child&&child.exitCode===null&&child.signalCode===null){child.kill('SIGTERM');await delay(300);if(master){try{process.kill(-master,'SIGCONT');process.kill(-master,'SIGTERM');}catch{}}if(child.exitCode===null&&child.signalCode===null)child.kill('SIGKILL');}
 report.fixtureUnchangedDuringTest=fixtureSha256===digest(await readFile(fixture));report.stderr=stderr;report.finishedAt=new Date().toISOString();console.log(JSON.stringify(report,null,2));if(!report.success||!report.fixtureUnchangedDuringTest)process.exitCode=1;
}

import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const source=await readFile('x10/test/all.mjs','utf8');const start=source.indexOf('function jsonChecks('),end=source.indexOf('\nasync function main()',start);assert.ok(start>=0&&end>start);const jsonChecks=Function(`return (${source.slice(start,end)})`)();
const record=JSON.parse(await readFile('x10/evidence/handover-fixed.json','utf8'));
const controls=[];
function check(name,mutate,expected=false){const x=structuredClone(record);mutate(x);let observed,error;try{observed=jsonChecks(x,'handover');}catch(e){error=e.message;}const passed=expected?observed===true:observed!==true;controls.push({name,expectedAccepted:expected,observedAccepted:observed===true,...(error?{threw:error}:{}),passed});assert.ok(passed,name);}
check('frozen-owner-record-accepted',()=>{},true);
const mutate=[
['unsuccessful-suite',d=>d.success=false],['interrupted-suite',d=>d.interrupted=true],['wrong-case-count',d=>d.tests.pop()],['failed-case',d=>d.tests[0].status='failed'],['skipped-case',d=>d.skips.push('review')],['fixture-error',d=>d.fixtureErrors.push('review')],['source-changed',d=>d.sourceUnchangedDuringTest=false],['binary-changed',d=>d.identity.binaryUnchangedDuringTest=false],['harness-changed',d=>d.identity.harnessUnchangedDuringTest=false],['observer-changed',d=>d.identity.observerUnchangedDuringTest=false],['invalid-binary-digest',d=>d.identity.binarySha256='invalid'],['native-log-not-read',d=>d.nativeErrorLogRead=false],['unexpected-native-error',d=>d.unexpectedNativeErrors.push('review')],['wrong-capture-scope',d=>d.observations.observerCapture.scope='complete-generation'],['missing-capture-digest',d=>delete d.observations.observerCapture.sha256],['all-snapshot-digests-absent',d=>{delete d.observations.observerCapture.sha256;delete d.observations.observerWhileStopped.snapshotSha256;delete d.observations.observerAfterResume.snapshotSha256;}],['wrong-pending-scope',d=>d.observations.observerWhileStopped.scope='complete-generation'],['wrong-closed-scope',d=>d.observations.observerAfterResume.scope='complete-generation'],['pending-state-closed',d=>d.observations.observerWhileStopped.state='closed'],['pending-boolean-closed',d=>d.observations.observerWhileStopped.closed=true],['no-pending-owner',d=>d.observations.observerWhileStopped.processes=[]],['closed-state-pending',d=>d.observations.observerAfterResume.state='pending'],['closed-boolean-false',d=>d.observations.observerAfterResume.closed=false],['closed-empty-capture-result',d=>d.observations.observerAfterResume.processes=[]],['closed-retains-listener',d=>d.observations.observerAfterResume.processes[0].state='owns-listener'],['snapshot-digest-mismatch',d=>d.observations.observerAfterResume.snapshotSha256='a'.repeat(64)],['native-still-running',d=>d.cleanup.nativeStopped=false],['native-failed-exit',d=>d.cleanup.nativeExitCode=1],['native-signal-exit',d=>d.cleanup.nativeSignal='SIGTERM'],['forced-cleanup-mode',d=>d.cleanup.mode='SIGTERM'],['stopped-worker-not-resumed',d=>d.cleanup.stoppedWorkerResumeRequested=false],['fixture-still-running',d=>d.cleanup.fixturesStopped=false],['open-socket',d=>d.cleanup.openSockets=1],['temporary-root-retained',d=>d.cleanup.temporaryRootRemoved=false],['cleanup-error',d=>d.cleanup.errors.push('review')]
];for(const [name,fn]of mutate)check(name,fn);
console.log(JSON.stringify({suite:'independent-handover-aggregate-direct-controls',kind:'direct extracted jsonChecks function; no aggregate CLI or real subprocess',sourceSha256:createHash('sha256').update(source).digest('hex'),evidenceSha256:createHash('sha256').update(await readFile('x10/evidence/handover-fixed.json')).digest('hex'),controls,success:controls.every(x=>x.passed)},null,2));
